      <span className="text-[var(--knock-muted,var(--knock-secondary))]">{label}</span>
      <strong className="font-medium">{recipient}</strong>
      <svg
        className="ml-1 text-[var(--knock-accent,var(--knock-highlight))]"
        aria-hidden="true"
        width="15"
        height="15"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
